Window.size = (1100, 700)

GARGANTUA_SPRITE_B64 = """"""




class StarRatingWidget(Widget):
    """Yıldızları font karakteri yerine Kivy ile çizer."""
    def __init__(self, stars=0, total=3, **kwargs):
        super().__init__(**kwargs)
        self.stars = max(0, min(int(total), int(stars)))
        self.total = int(total)
        self.bind(pos=self.redraw, size=self.redraw)
        self.redraw()

    def _points(self, cx, cy, outer_r, inner_r):
        pts = []
        for i in range(10):
            a = -math.pi / 2 + i * math.pi / 5
            r = outer_r if i % 2 == 0 else inner_r
            pts.extend([
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            ])
        return pts

    def redraw(self, *_):
        self.canvas.clear()

        if self.width <= 0 or self.height <= 0:
            return

        with self.canvas:
            spacing = min(self.width / max(1, self.total), self.height * 1.15)
            outer = min(spacing * .34, self.height * .42)
            inner = outer * .44
            group_width = spacing * (self.total - 1)
            first_x = self.center_x - group_width / 2

            for i in range(self.total):
                cx = first_x + i * spacing
                cy = self.center_y
                pts = self._points(cx, cy, outer, inner)

                # Merkezi kullanarak yıldızın içini 10 üçgenle doldur.
                vertices = [cx, cy, 0, 0]
                for j in range(0, len(pts), 2):
                    vertices.extend([pts[j], pts[j + 1], 0, 0])
                vertices.extend([pts[0], pts[1], 0, 0])

                indices = []
                vertex_count = 12
                for j in range(1, vertex_count - 1):
                    indices.extend([0, j, j + 1])

                if i < self.stars:
                    Color(1.0, .70, .08, 1)
                else:
                    Color(.10, .15, .21, 1)

                Mesh(
                    vertices=vertices,
                    indices=indices,
                    mode="triangles"
                )

                if i < self.stars:
                    Color(1.0, .92, .36, 1)
                else:
                    Color(.30, .42, .52, 1)

                Line(
                    points=pts,
                    close=True,
                    width=1.4
                )


class SpaceScene(Widget):
    def __init__(self, game, **kwargs):
        super().__init__(**kwargs)
        self.game = game

        raw = base64.b64decode(GARGANTUA_SPRITE_B64)
        self.gargantua_texture = CoreImage(BytesIO(raw), ext="png").texture

        self.stars = []
        for _ in range(340):
            self.stars.append({
                "x": random.uniform(-5200, 5200),
                "z": random.uniform(-5600, 5600),
                "y": random.uniform(-1200, 1200),
                "size": random.uniform(0.7, 2.3)
            })

    def project(self, world_x, world_z, world_y=0):
        g = self.game

        rel_x = world_x - g.ship_x
        rel_z = world_z - g.ship_z
        rel_y = world_y

        if rel_z <= 20:
            return None

        focal = 760.0

        sx = 550 + g.camera_shake_x + (rel_x / rel_z) * focal
        sy = 375 + g.camera_shake_y + (rel_y / rel_z) * focal

        return sx, sy, rel_z

    def draw_gargantua(self, bh):
        p = self.project(bh["x"], bh["z"], 0)
        if not p:
            return

        bx, by, depth = p

        sprite_world_width = bh.get("visual_width", 1900.0)
        screen_w = sprite_world_width * 760.0 / depth
        screen_w = max(82, min(1320, screen_w))

        aspect = 1250 / 675
        screen_h = screen_w / aspect

        if not (-950 < bx < 2050):
            return

        # Aynı, kullanıcının beğendiği Gargantua sprite'ı.
        Color(1, .34, .04, .032)
        Ellipse(
            pos=(bx-screen_w*.31, by-screen_h*.42),
            size=(screen_w*.62, screen_h*.84)
        )

        Color(1, 1, 1, 1)
        Rectangle(
            texture=self.gargantua_texture,
            pos=(bx-screen_w/2, by-screen_h/2),
            size=(screen_w, screen_h)
        )

        # Çok hafif canlı foton halkası.
        t = time.time()
        pulse = .5 + .5 * math.sin(t * 2.0 + bh["x"] * .001)
        ring_r = min(screen_w, screen_h) * .275

        Color(1, .97, .84, .09 + pulse*.035)
        Line(
            circle=(bx, by+4, ring_r),
            width=max(1.0, screen_w*.0018)
        )

    def draw_station(self):
        g = self.game

        if g.level != 1:
            return

        p = self.project(g.station_x, g.station_z, 40)
        if not p:
            return

        sx, sy, depth = p

        scale = 760.0 / max(180.0, depth)
        w = max(220, min(650, 620 * scale))
        h = w * .42

        if not (-500 < sx < 1600):
            return

        # Uzay baz istasyonu
        Color(.03,.07,.11,.96)
        Rectangle(
            pos=(sx-w*.45, sy-h*.22),
            size=(w*.90, h*.44)
        )

        # Merkez gövde
        Color(.12,.18,.24,1)
        Rectangle(
            pos=(sx-w*.12, sy-h*.42),
            size=(w*.24, h*.84)
        )

        # Yan modüller
        Color(.08,.13,.20,1)
        Rectangle(
            pos=(sx-w*.56, sy-h*.16),
            size=(w*.22, h*.32)
        )
        Rectangle(
            pos=(sx+w*.34, sy-h*.16),
            size=(w*.22, h*.32)
        )

        # Güneş panelleri
        Color(.04,.19,.34,1)
        Rectangle(
            pos=(sx-w*.86, sy-h*.11),
            size=(w*.28, h*.22)
        )
        Rectangle(
            pos=(sx+w*.58, sy-h*.11),
            size=(w*.28, h*.22)
        )

        Color(.10,.65,1,.75)
        Line(
            rectangle=(sx-w*.86, sy-h*.11, w*.28, h*.22),
            width=max(1.0,w*.005)
        )
        Line(
            rectangle=(sx+w*.58, sy-h*.11, w*.28, h*.22),
            width=max(1.0,w*.005)
        )

        # Anten
        Color(.6,.75,.85,1)
        Line(
            points=[sx, sy+h*.42, sx, sy+h*.76],
            width=max(1.2,w*.006)
        )
        Line(
            circle=(sx, sy+h*.82, max(3,w*.018)),
            width=max(1.0,w*.004)
        )

        # Işıklar
        blink = .45 + .55*(.5+.5*math.sin(time.time()*5))
        Color(.15,1,.55,blink)
        Ellipse(
            pos=(sx-w*.045, sy-h*.04),
            size=(w*.09,w*.09)
        )

        Color(.15,.75,1,.8)
        Line(
            rectangle=(sx-w*.45, sy-h*.22, w*.90, h*.44),
            width=max(1.0,w*.005)
        )

        Color(.25,.95,1,.85)
        Line(
            circle=(sx, sy, max(22, w*.11)),
            width=max(1.6, w*.008)
        )

        Color(.20,1,.55,.95)
        Ellipse(
            pos=(sx-max(3,w*.018), sy-max(3,w*.018)),
            size=(max(6,w*.036), max(6,w*.036))
        )

    def draw_meteors(self):
        g = self.game

        if not g.intro_active:
            return

        for m in g.meteors:
            p = self.project(m["x"], m["z"], m["y"])
            if not p:
                continue

            sx, sy, depth = p

            if not (-100 < sx < 1200 and -100 < sy < 800):
                continue

            size = max(12, min(100, m["size"] * 950.0 / max(120.0, depth)))

            # Çok belirgin ateş kuyruğu
            Color(1,.10,.01,.15)
            Line(
                points=[
                    sx, sy,
                    sx + 60 + size*2.8,
                    sy + 32 + size*.9
                ],
                width=max(4.0,size*.50)
            )

            Color(1,.68,.12,.55)
            Line(
                points=[
                    sx, sy,
                    sx + 38 + size*1.8,
                    sy + 20 + size*.55
                ],
                width=max(2.0,size*.22)
            )

            Color(.48,.24,.12,1)
            Ellipse(
                pos=(sx-size/2, sy-size/2),
                size=(size,size)
            )

            Color(1,.55,.12,.55)
            Line(
                circle=(sx,sy,size*.52),
                width=max(1.0,size*.10)
            )

    def draw_pickups(self):
        g = self.game

        for item in g.pickups:
            if item.get("collected"):
                continue

            p = self.project(item["x"], item["z"], item.get("y", 0))
            if not p:
                continue

            sx, sy, depth = p
            size = max(12, min(58, 78 * 760.0 / max(180.0, depth)))

            if item["type"] == "repair":
                Color(.08, 1.0, .42, .12)
                Ellipse(
                    pos=(sx-size*.75, sy-size*.75),
                    size=(size*1.5, size*1.5)
                )
                Color(.18, 1.0, .48, .95)
            else:
                Color(.05, .52, 1.0, .13)
                Ellipse(
                    pos=(sx-size*.75, sy-size*.75),
                    size=(size*1.5, size*1.5)
                )
                Color(.18, .72, 1.0, .95)

            Line(circle=(sx, sy, size*.55), width=max(1.5, size*.08))
            Line(circle=(sx, sy, size*.33), width=max(1.0, size*.04))

            if item["type"] == "repair":
                Line(points=[sx-size*.22,sy,sx+size*.22,sy], width=max(2,size*.08))
                Line(points=[sx,sy-size*.22,sx,sy+size*.22], width=max(2,size*.08))
            else:
                Line(
                    points=[
                        sx,sy+size*.23,
                        sx-size*.20,sy+size*.05,
                        sx-size*.12,sy-size*.25,
                        sx,sy-size*.34,
                        sx+size*.12,sy-size*.25,
                        sx+size*.20,sy+size*.05,
                        sx,sy+size*.23
                    ],
                    width=max(1.5,size*.055)
                )

    def draw_wormhole(self):
        g = self.game
        if g.level != 4 or not g.wormhole:
            return

        # Portalın içine girdikten sonra artık dünya koordinatına bağlı
        # değildir; tam ekran hız tüneli olarak görünür.
        if g.wormhole_tunnel_active:
            now = time.time()
            progress = min(1.0, g.wormhole_tunnel_time / 3.2)

            Color(.015,.005,.04,.96)
            Rectangle(pos=(0,145), size=(1100,555))

            for i in range(22):
                rr = 30 + ((i*52 + int(now*520)) % 820)
                alpha = max(.025, .27 - rr/4200)

                if i % 3 == 0:
                    Color(.55,.20,1,alpha)
                else:
                    Color(.16,.68,1,alpha)

                Line(
                    ellipse=(550-rr, 375-rr*.52, rr*2, rr*1.04),
                    width=2.0 + progress*2.5
                )

            Color(.80,.96,1,.82)
            Line(circle=(550,375,42+progress*35), width=3)
            return

        p = self.project(g.wormhole["x"], g.wormhole["z"], 0)
        if not p:
            return

        wx, wy, depth = p
        apparent = 520.0 * 760.0 / max(100.0, depth)
        r = max(50, min(520, apparent))
        now = time.time()

        # Space fracture / shards
        for i, shard in enumerate(g.space_shards):
            ang = shard["angle"] + now * shard["speed"]
            rr = r * shard["radius"]
            x1 = wx + math.cos(ang) * rr
            y1 = wy + math.sin(ang) * rr
            x2 = wx + math.cos(ang + shard["twist"]) * rr * 1.24
            y2 = wy + math.sin(ang + shard["twist"]) * rr * 1.24

            Color(.22,.62,1,.10 + (i%3)*.03)
            Line(points=[x1,y1,x2,y2], width=1.2)

        # Layered portal rings
        for i in range(11):
            phase = (now*1.7 + i*.37) % 1.0
            rr = r * (0.28 + i*.085 + phase*.035)

            if i % 3 == 0:
                Color(.55,.18,1,.28)
            elif i % 3 == 1:
                Color(.08,.72,1,.34)
            else:
                Color(1,.88,1,.22)

            Line(
                ellipse=(
                    wx-rr,
                    wy-rr*.48,
                    rr*2,
                    rr*.96
                ),
                width=max(1.2, r*.010)
            )

        Color(.015,.005,.04,.98)
        Ellipse(
            pos=(wx-r*.34, wy-r*.26),
            size=(r*.68, r*.52)
        )

        Color(.78,.92,1,.82)
        Line(
            ellipse=(wx-r*.40, wy-r*.30, r*.80, r*.60),
            width=max(2.0,r*.020)
        )

    def draw_damage_overlay(self):
        g = self.game
        now = time.time()

        # Hit flash
        if g.damage_flash > 0:
            Color(1,.03,.01,min(.20,g.damage_flash*.20))
            Rectangle(pos=(0,0), size=(1100,700))

        # Cockpit glass cracks appear after meaningful damage.
        damage = max(
            0.0,
            1.0 - min(g.hull, g.shield) / 100.0
        )

        if damage > .18:
            alpha = min(.65, .16 + damage*.55)
            Color(.78,.90,1,alpha)

            # fixed crack pattern so it looks stable, not random every frame
            crack_sets = [
                [(780,560),(744,520),(718,478),(676,451)],
                [(780,560),(823,535),(855,493),(910,470)],
                [(780,560),(792,510),(770,463),(786,420)],
                [(315,520),(348,482),(365,438),(410,405)],
                [(315,520),(270,486),(235,445),(205,412)],
            ]

            count = 2 if damage < .45 else (4 if damage < .70 else 5)

            for pts in crack_sets[:count]:
                flat = []
                for x,y in pts:
                    flat.extend([x,y])
                Line(points=flat, width=1.15)

        # Visual alarm below 50%, critical below 20%.
        if g.shield < 50 or g.hull < 50:
            pulse = .5 + .5*math.sin(now*8.5)
            Color(1,.02,.01,.025 + pulse*.045)
            Rectangle(pos=(0,145), size=(1100,555))

            if min(g.shield, g.hull) < 20:
                Color(1,.01,.01,.06 + pulse*.09)
                Rectangle(pos=(0,0), size=(1100,700))

    def draw_real_radar(self, cx, cy, radius=30, radar_range=2600.0):
        """
        Gerçek radar:
        merkez = oyuncu
        yukarı = geminin baktığı +Z yönü
        sağ/sol = dünya X koordinatı
        """
        g = self.game

        targets = []

        # Kara delikler
        for bh in g.blackholes:
            targets.append((
                bh["x"], bh["z"],
                "blackhole"
            ))

        # Toplanabilir kapsüller
        for item in g.pickups:
            if not item.get("collected"):
                targets.append((
                    item["x"], item["z"],
                    item["type"]
                ))

        # Pulsar
        if g.level == 3 and g.pulsar:
            targets.append((
                g.pulsar["x"], g.pulsar["z"],
                "pulsar"
            ))

        # Void Master
        if g.level == 2 and g.void_master_active and g.void_master:
            targets.append((
                g.void_master["x"], g.void_master["z"],
                "void"
            ))

        # Solucan deliği
        if g.level == 4 and g.wormhole:
            targets.append((
                g.wormhole["x"], g.wormhole["z"],
                "wormhole"
            ))

        # Level 5 güvenli kaçış kapısı
        if g.level == 5:
            targets.append((0.0,g.supernova_goal_z,"safe"))

        # Level 7 kayıp istasyon
        if g.level == 7 and g.lost_station:
            targets.append((
                g.lost_station["x"],g.lost_station["z"],"station"
            ))

        # Level 8 düşman filosu
        if g.level == 8:
            for e in g.enemy_fleet:
                if e["hp"] > 0:
                    targets.append((e["x"],e["z"],"enemy"))

        # Level 9 crystal boss
        if g.level == 9 and g.crystal_boss:
            targets.append((
                g.crystal_boss["x"],g.crystal_boss["z"],"crystalboss"
            ))

        # Level 20 final boss
        if g.level == 20 and g.omega:
            targets.append((g.omega["x"],g.omega["z"],"omega"))

        # Meteorlar: sadece en yakın birkaçını radarda göster.
        if g.intro_active:
            nearest_meteors = sorted(
                g.meteors,
                key=lambda m: abs(m["z"]-g.ship_z) + abs(m["x"]-g.ship_x)
            )[:8]

            for m in nearest_meteors:
                targets.append((
                    m["x"], m["z"],
                    "meteor"
                ))

        for tx, tz, typ in targets:
            dx = tx - g.ship_x
            dz = tz - g.ship_z
            distance = math.hypot(dx, dz)

            if distance > radar_range:
                continue

            # radar ekranına ölçekle
            scale = radius / radar_range
            px = cx + dx * scale
            py = cy + dz * scale

            # Noktanın radar dairesinin dışına taşmasını engelle.
            ddx = px - cx
            ddy = py - cy
            d = math.hypot(ddx, ddy)

            if d > radius - 3:
                k = (radius - 3) / max(1.0, d)
                px = cx + ddx*k
                py = cy + ddy*k

            if typ == "blackhole":
                Color(1.0,.30,.04,.95)
                dot = 5.2

            elif typ == "meteor":
                Color(1.0,.10,.04,.95)
                dot = 3.2

            elif typ == "repair":
                Color(.15,1.0,.44,.95)
                dot = 4.0

            elif typ == "shield":
                Color(.12,.72,1.0,.95)
                dot = 4.0

            elif typ == "pulsar":
                Color(.82,.35,1.0,.98)
                dot = 5.5

            elif typ == "void":
                Color(.70,.10,1.0,.98)
                dot = 6.0

            elif typ == "wormhole":
                Color(.35,.94,1.0,.98)
                dot = 6.0

            elif typ in ("enemy","omega"):
                Color(1.0,.12,.12,.98)
                dot = 5.5

            elif typ == "crystalboss":
                Color(.72,.30,1.0,.98)
                dot = 5.5

            elif typ == "safe":
                Color(.20,1.0,.70,.98)
                dot = 5.0

            else:  # station
                Color(.30,.80,1.0,.98)
                dot = 5.0

            Ellipse(
                pos=(px-dot/2, py-dot/2),
                size=(dot,dot)
            )

        # Oyuncu her zaman radarın merkezinde.
        Color(.30,1.0,.62,1)
        Triangle(points=[
            cx, cy+5,
            cx-4, cy-4,
            cx+4, cy-4
        ])

    # ======================================================
    # LEVEL 5 - SUPERNOVA
    # ======================================================

    def draw_supernova_level(self):
        g = self.game
        if g.level != 5:
            return

        now = time.time()

        # Patlama arkada olduğu için kokpit camına yansıyan sıcak ışık.
        gap = max(0.0, g.ship_z - g.supernova_wave_z)
        danger = max(0.0, min(1.0, (1500.0-gap)/1500.0))

        pulse = .5 + .5*math.sin(now*8)

        Color(1.0,.14,.01,.035 + danger*.12 + pulse*danger*.04)
        Rectangle(pos=(145,180), size=(810,475))

        # Arkadan yaklaşan şok dalgası kenar parlamaları.
        if danger > 0:
            Color(1.0,.32,.02,.06 + danger*.20)
            Line(
                ellipse=(
                    550-(430+danger*270),
                    375-(240+danger*140),
                    (430+danger*270)*2,
                    (240+danger*140)*2
                ),
                width=8 + danger*18
            )

        # Güvenli kaçış kapısı / beacon önde.
        p = self.project(0.0, g.supernova_goal_z, 0)
        if p:
            sx,sy,depth = p
            rr = max(24,min(150,230*760/max(180,depth)))

            Color(.10,.78,1,.14)
            Ellipse(pos=(sx-rr,sy-rr), size=(rr*2,rr*2))
            Color(.34,.96,1,.82)
            Line(circle=(sx,sy,rr*.72), width=max(2,rr*.035))
            Line(circle=(sx,sy,rr*.45), width=max(1,rr*.018))

    # ======================================================
    # LEVEL 7 - LOST SPACE STATION
    # ======================================================

    def draw_lost_station(self):
        g = self.game
        if g.level != 7 or not g.lost_station:
            return

        p = self.project(g.lost_station["x"], g.lost_station["z"], 20)
        if not p:
            return

        sx,sy,depth = p
        w = max(120,min(650,720*760/max(200,depth)))
        h = w*.38
        now = time.time()

        # Kırık, karanlık istasyon gövdesi
        Color(.025,.035,.045,1)
        Rectangle(pos=(sx-w*.42,sy-h*.18), size=(w*.84,h*.36))

        Color(.09,.12,.16,1)
        Rectangle(pos=(sx-w*.10,sy-h*.46), size=(w*.20,h*.92))

        # kırık kanatlar
        Color(.035,.10,.16,1)
        Rectangle(pos=(sx-w*.76,sy-h*.10), size=(w*.27,h*.20))
        Rectangle(pos=(sx+w*.49,sy-h*.10), size=(w*.22,h*.20))

        Color(.16,.66,1,.42)
        Line(rectangle=(sx-w*.76,sy-h*.10,w*.27,h*.20), width=1.5)

        # Eksik/kırık sağ panel çizgileri
        Color(.55,.20,.10,.55)
        Line(points=[
            sx+w*.49,sy-h*.10,
            sx+w*.70,sy+h*.08,
            sx+w*.62,sy-h*.15
        ], width=2)

        # Tarama alanı
        scan = g.station_scan_progress / max(.1,g.station_scan_required)
        scan_r = w*(.30 + .10*math.sin(now*2.5))

        Color(.12,.82,1,.10)
        Line(circle=(sx,sy,scan_r), width=3)

        Color(.15,1,.58,.55)
        Line(
            circle=(sx,sy,w*.17),
            width=max(1.5,w*.006)
        )

        # EMP pulse
        if g.station_pulse_flash > 0:
            rr = w*(.25 + (1-g.station_pulse_flash)*.85)
            Color(.35,.64,1,.22*g.station_pulse_flash)
            Line(circle=(sx,sy,rr), width=8*g.station_pulse_flash+1)

    # ======================================================
    # LEVEL 8 - DARK FLEET
    # ======================================================

    def draw_player_weapon_laser(self):
        g = self.game
        if g.player_laser_flash <= 0 or not g.player_laser_target:
            return

        target = g.player_laser_target
        p = self.project(target[0],target[1],target[2])
        if not p:
            return

        tx,ty,_ = p
        Color(.22,1,.82,min(1,g.player_laser_flash*2.3))
        Line(points=[550,385,tx,ty],width=4)
        Color(1,1,1,min(1,g.player_laser_flash*2.3))
        Line(points=[550,385,tx,ty],width=1.4)

    def draw_enemy_fleet(self):
        g = self.game
        if g.level != 8:
            return

        now = time.time()

        for e in g.enemy_fleet:
            if e["hp"] <= 0:
                continue

            p = self.project(e["x"],e["z"],e.get("y",0))
            if not p:
                continue

            sx,sy,depth = p
            size = max(18,min(125,155*760/max(190,depth)))

            # düşman savaş gemisi
            Color(.20,.03,.045,1)
            Triangle(points=[
                sx,sy+size*.45,
                sx-size*.50,sy-size*.38,
                sx+size*.50,sy-size*.38
            ])

            Color(.80,.08,.12,.78)
            Line(points=[
                sx,sy+size*.45,
                sx-size*.50,sy-size*.38,
                sx+size*.50,sy-size*.38,
                sx,sy+size*.45
            ], width=max(1.5,size*.025))

            Color(1,.25,.08,.85)
            Ellipse(
                pos=(sx-size*.07,sy-size*.08),
                size=(size*.14,size*.14)
            )

            # HP bar
            Color(.08,.02,.02,.8)
            Rectangle(pos=(sx-size*.42,sy-size*.55), size=(size*.84,5))
            Color(1,.14,.08,.9)
            Rectangle(
                pos=(sx-size*.42,sy-size*.55),
                size=(size*.84*max(0,e["hp"])/30.0,5)
            )

        # Oyuncu lazeri
        if g.player_laser_flash > 0 and g.player_laser_target:
            target = g.player_laser_target
            p = self.project(target[0],target[1],target[2])
            if p:
                tx,ty,_ = p
                Color(.25,1,.86,min(1,g.player_laser_flash*2))
                Line(points=[550,385,tx,ty], width=4)
                Color(1,1,1,min(1,g.player_laser_flash*2))
                Line(points=[550,385,tx,ty], width=1.5)

        # Düşman lazeri
        if g.enemy_laser_flash > 0 and g.enemy_laser_origin:
            p = self.project(
                g.enemy_laser_origin[0],
                g.enemy_laser_origin[1],
                g.enemy_laser_origin[2]
            )
            if p:
                ex,ey,_ = p
                Color(1,.06,.03,min(.9,g.enemy_laser_flash*1.8))
                Line(points=[ex,ey,550,385], width=5)

    # ======================================================
    # LEVEL 9 - CRYSTAL GALAXY
    # ======================================================

    def draw_crystal_level(self):
        g = self.game
        if g.level != 9:
            return

        now = time.time()

        for c in g.crystals:
            if c.get("broken"):
                continue

            p = self.project(c["x"],c["z"],c["y"])
            if not p:
                continue

            sx,sy,depth = p
            size = max(10,min(100,c["size"]*760/max(150,depth)))

            if c["kind"] == 0:
                Color(.16,.68,1,.68)
            elif c["kind"] == 1:
                Color(.70,.20,1,.66)
            else:
                Color(.10,1,.65,.62)

            Triangle(points=[
                sx,sy+size,
                sx-size*.50,sy-size*.20,
                sx,sy-size,
            ])
            Triangle(points=[
                sx,sy+size,
                sx+size*.50,sy-size*.20,
                sx,sy-size,
            ])

            Color(.82,.96,1,.35)
            Line(points=[sx,sy+size,sx,sy-size], width=1)

        # Crystal Leviathan
        if g.crystal_boss:
            p = self.project(
                g.crystal_boss["x"],
                g.crystal_boss["z"],
                0
            )
            if p:
                bx,by,depth = p
                r = max(35,min(250,310*760/max(180,depth)))
                pulse = .5+.5*math.sin(now*5)

                Color(.35,.10,.72,.10+pulse*.04)
                Ellipse(pos=(bx-r*1.5,by-r*1.5),size=(r*3,r*3))

                Color(.48,.18,1,.88)
                Triangle(points=[
                    bx,by+r,
                    bx-r*.76,by-r*.55,
                    bx+r*.76,by-r*.55
                ])
                Color(.12,.85,1,.75)
                Triangle(points=[
                    bx,by-r,
                    bx-r*.60,by+r*.30,
                    bx+r*.60,by+r*.30
                ])

                Color(1,.90,1,.92)
                Ellipse(pos=(bx-r*.13,by-r*.13),size=(r*.26,r*.26))

                # boss bar visual above boss
                Color(.05,.01,.08,.9)
                Rectangle(pos=(bx-r,by+r*1.18),size=(r*2,8))
                Color(.65,.18,1,.9)
                Rectangle(
                    pos=(bx-r,by+r*1.18),
                    size=(r*2*max(0,g.crystal_boss_health)/100.0,8)
                )

    # ======================================================
    # LEVEL 20 - VOID MASTER OMEGA
    # ======================================================

    def draw_omega(self):
        g = self.game
        if g.level != 20 or not g.omega:
            return

        p = self.project(g.omega["x"],g.omega["z"],0)
        if not p:
            return

        ox,oy,depth = p
        r = max(70,min(360,430*760/max(180,depth)))
        now = time.time()

        if g.omega_exploding:
            progress = min(1.0,g.omega_explosion_time/3.0)
            rr = r*(1+progress*6)

            Color(1,1,1,max(0,.9-progress*.85))
            Ellipse(pos=(ox-rr*.42,oy-rr*.42),size=(rr*.84,rr*.84))

            Color(.55,.08,1,max(0,.48-progress*.42))
            Ellipse(pos=(ox-rr,oy-rr),size=(rr*2,rr*2))

            for i in range(5):
                ring = r*(1.2+progress*(2.5+i*.9))
                Color(.25,.72,1,max(.03,.55-progress*.48))
                Line(circle=(ox,oy,ring),width=max(1,8-progress*5))
            return

        hp_ratio = max(0,g.omega_health)/300.0
        phase = 1 if hp_ratio > .66 else (2 if hp_ratio > .33 else 3)

        Color(.18,.01,.36,.08)
        Ellipse(pos=(ox-r*1.65,oy-r*1.65),size=(r*3.3,r*3.3))

        # rotating rings
        Color(.65,.10,1,.50)
        Line(ellipse=(ox-r*1.55,oy-r*.50,r*3.1,r),width=max(2,r*.028))
        Color(.08,.70,1,.38)
        Line(ellipse=(ox-r*.60,oy-r*1.50,r*1.2,r*3),width=max(1.5,r*.020))

        # core
        Color(0,0,.005,1)
        Ellipse(pos=(ox-r,oy-r),size=(r*2,r*2))

        core_color = [
            (.66,.18,1,.95),
            (.20,.72,1,.95),
            (1,.12,.18,.98)
        ][phase-1]
        Color(*core_color)
        Line(circle=(ox,oy,r*1.035),width=max(3,r*.026))

        Color(1,1,1,.92)
        Ellipse(pos=(ox-r*.18,oy-r*.05),size=(r*.36,r*.10))

        # Gamma attack visualization
        if g.omega_gamma_active:
            elapsed = now-g.omega_gamma_started
            target_p = self.project(g.omega_gamma_target_x,g.ship_z+650,0)
            if target_p:
                tx,ty,_ = target_p
            else:
                tx,ty = 550,385

            if elapsed < 1.0:
                Color(1,.08,.18,.75)
                Line(circle=(tx,ty,60+20*math.sin(now*12)),width=3)
                Color(.72,.14,1,.35)
                Line(points=[ox,oy,tx,ty],width=2)
            elif elapsed < 1.7:
                Color(.50,.18,1,.30)
                Line(points=[ox,oy,tx,ty],width=48)
                Color(1,.90,1,.95)
                Line(points=[ox,oy,tx,ty],width=7)

        # Orbs
        for orb in g.omega_orbs:
            if not orb.get("active",True):
                continue
            p2 = self.project(orb["x"],orb["z"],orb.get("y",0))
            if p2:
                sx,sy,depth2 = p2
                size=max(8,min(60,70*760/max(150,depth2)))
                Color(.55,.12,1,.22)
                Ellipse(pos=(sx-size,sy-size),size=(size*2,size*2))
                Color(.85,.54,1,.90)
                Ellipse(pos=(sx-size*.34,sy-size*.34),size=(size*.68,size*.68))

    def draw_void_master(self):
        g = self.game

        if (
            g.level != 2
            or not g.void_master_active
            or not g.void_master
        ):
            return

        p = self.project(
            g.void_master["x"],
            g.void_master["z"],
            0
        )

        if not p:
            return

        vx, vy, depth = p

        apparent_r = 390.0 * 760.0 / max(120.0, depth)
        r = max(54, min(285, apparent_r))

        now = time.time()
        pulse = .5 + .5 * math.sin(now * 2.8)
        fast = .5 + .5 * math.sin(now * 8.5)

        # -----------------------------------------------
        # VOID MASTER - KOYU MOR / SIYAH DEV VARLIK
        # -----------------------------------------------
        Color(.18, .02, .42, .035 + pulse*.035)
        Ellipse(
            pos=(vx-r*1.85, vy-r*1.85),
            size=(r*3.70, r*3.70)
        )

        Color(.52, .05, .85, .08 + pulse*.05)
        Ellipse(
            pos=(vx-r*1.42, vy-r*1.42),
            size=(r*2.84, r*2.84)
        )

        # Dönen void halkaları
        Color(.55, .12, 1.0, .42)
        Line(
            ellipse=(vx-r*1.85, vy-r*.50, r*3.70, r*1.0),
            width=max(2.0, r*.030)
        )

        Color(.18, .62, 1.0, .24)
        Line(
            ellipse=(vx-r*.78, vy-r*1.82, r*1.56, r*3.64),
            width=max(1.4, r*.018)
        )

        # Siyah çekirdek
        Color(.002, .001, .008, 1)
        Ellipse(
            pos=(vx-r, vy-r),
            size=(r*2, r*2)
        )

        # Mor foton/enerji halkası
        Color(.82, .42, 1.0, .82 + fast*.12)
        Line(
            circle=(vx, vy, r*1.035),
            width=max(2.0, r*.018)
        )

        Color(.35, .82, 1.0, .28)
        Line(
            circle=(vx, vy, r*1.13),
            width=max(1.2, r*.010)
        )

        # Merkez "göz" / enerji yarığı
        Color(.72, .22, 1.0, .55 + fast*.40)
        Ellipse(
            pos=(vx-r*.20, vy-r*.055),
            size=(r*.40, r*.11)
        )

        Color(1, .90, 1, .75)
        Line(
            points=[vx-r*.16, vy, vx+r*.16, vy],
            width=max(1.2, r*.012)
        )

        # -----------------------------------------------
        # GAMA IŞINI PATLAMASI
        # -----------------------------------------------
        if not g.void_gamma_active:
            return

        elapsed = now - g.void_gamma_started_at

        target_p = self.project(
            g.void_gamma_target_x,
            g.void_gamma_target_z,
            0
        )

        if not target_p:
            target_x = 550
            target_y = 375
        else:
            target_x, target_y, _ = target_p

        # 0 - 1.25 sn: hedef uyarısı
        if elapsed < 1.25:
            warning_pulse = .4 + .6 * (.5 + .5*math.sin(now*13))

            Color(1, .06, .08, .35 + warning_pulse*.35)
            Line(
                circle=(target_x, target_y, 55 + warning_pulse*20),
                width=3
            )

            Color(.95, .10, 1.0, .45)
            Line(
                points=[vx, vy, target_x, target_y],
                width=2
            )

            Color(1, .12, .10, .15)
            Rectangle(
                pos=(target_x-72, 145),
                size=(144, 465)
            )

        # 1.25 - 2.10 sn: GAMA PATLAMASI
        elif elapsed < 2.10:
            blast_progress = (elapsed - 1.25) / .85
            blast_pulse = .5 + .5*math.sin(now*28)

            # Gama ışını ana kolonu
            Color(.42, .14, 1.0, .18)
            Line(
                points=[vx, vy, target_x, target_y],
                width=52
            )

            Color(.35, .72, 1.0, .42)
            Line(
                points=[vx, vy, target_x, target_y],
                width=24
            )

            Color(1, .94, 1.0, .92)
            Line(
                points=[vx, vy, target_x, target_y],
                width=6 + blast_pulse*4
            )

            # Hedefte gama patlaması
            explosion_r = 80 + blast_progress * 165

            Color(.54, .08, 1.0, max(.08, .42-blast_progress*.28))
            Ellipse(
                pos=(target_x-explosion_r, target_y-explosion_r),
                size=(explosion_r*2, explosion_r*2)
            )

            Color(.25, .76, 1.0, max(.12, .75-blast_progress*.48))
            Line(
                circle=(target_x, target_y, explosion_r*1.25),
                width=max(3, 12-blast_progress*7)
            )

            Color(1, 1, 1, max(.10, .85-blast_progress*.65))
            Line(
                circle=(target_x, target_y, explosion_r*.58),
                width=max(2, 8-blast_progress*4)
            )

    def draw_pulsar(self):
        g = self.game
        if g.level != 3 or not g.pulsar:
            return

        p = self.project(g.pulsar["x"], g.pulsar["z"], 0)
        if not p:
            return

        px, py, depth = p
        apparent_r = 330.0 * 760.0 / depth
        r = max(18, min(260, apparent_r))
        now = time.time()

        # ==================================================
        # PULSAR YENİLDİ: DEV PATLAMA
        # ==================================================
        if g.pulsar_exploding:
            progress = min(
                1.0,
                g.pulsar_explosion_time / g.pulsar_explosion_duration
            )

            # İlk anda beyaz çekirdek parlaması
            flash_alpha = max(0.0, 1.0 - progress * 2.4)

            if flash_alpha > 0:
                Color(1, 1, 1, flash_alpha)
                flash_r = r * (1.2 + progress * 4.0)
                Ellipse(
                    pos=(px-flash_r, py-flash_r),
                    size=(flash_r*2, flash_r*2)
                )

            # Mavi-beyaz iç patlama
            inner = r * (1.0 + progress * 3.8)
            Color(.42, .86, 1.0, max(0.0, .72-progress*.65))
            Ellipse(
                pos=(px-inner, py-inner),
                size=(inner*2, inner*2)
            )

            # Turuncu sıcak dış şok
            hot = r * (1.4 + progress * 5.2)
            Color(1.0, .22, .015, max(0.0, .30-progress*.25))
            Ellipse(
                pos=(px-hot, py-hot),
                size=(hot*2, hot*2)
            )

            # Dev şok dalgası halkaları
            for i in range(4):
                local = max(0.0, min(1.0, progress*1.25 - i*.12))

                if local > 0:
                    ring_r = r * (1.3 + local*(5.0+i*.75))
                    alpha = max(0.0, .76-local*.68)

                    if i % 2 == 0:
                        Color(.55, .92, 1.0, alpha)
                    else:
                        Color(1.0, .45, .08, alpha*.82)

                    Line(
                        circle=(px, py, ring_r),
                        width=max(2.0, r*(.055-local*.030))
                    )

            # Dışarı saçılan parçalar
            for i in range(28):
                ang = i * (math.pi*2/28) + math.sin(i*3.1)*.17
                travel = r * (1.0 + progress*(4.0 + (i%5)*.40))
                fx = px + math.cos(ang) * travel
                fy = py + math.sin(ang) * travel

                dot = max(1.5, r*.035*(1.0-progress*.55))

                if i % 3 == 0:
                    Color(1.0, .50, .08, max(.05, .72-progress*.62))
                else:
                    Color(.52, .90, 1.0, max(.05, .68-progress*.58))

                Line(
                    points=[
                        px + math.cos(ang)*r*.85,
                        py + math.sin(ang)*r*.85,
                        fx,
                        fy
                    ],
                    width=max(1.0, dot*.45)
                )

                Ellipse(
                    pos=(fx-dot, fy-dot),
                    size=(dot*2, dot*2)
                )

            # Patlama sırasında normal pulsar ve ışınlar çizilmez.
            return

        # Electric halo
        pulse = 0.5 + 0.5 * math.sin(now * 8.0)

        Color(.10, .55, 1.0, .05 + pulse*.04)
        Ellipse(
            pos=(px-r*2.0, py-r*2.0),
            size=(r*4.0, r*4.0)
        )

        # Magnetosphere rings
        Color(.15, .72, 1.0, .35)
        Line(
            ellipse=(px-r*1.55, py-r*.62, r*3.10, r*1.24),
            width=max(1.0, r*.025)
        )

        Color(.60, .22, 1.0, .24)
        Line(
            ellipse=(px-r*.80, py-r*1.55, r*1.60, r*3.10),
            width=max(1.0, r*.018)
        )

        # Pulsar body
        Color(.04, .12, .24, 1)
        Ellipse(
            pos=(px-r, py-r),
            size=(r*2, r*2)
        )

        Color(.75, .92, 1.0, .94)
        Ellipse(
            pos=(px-r*.65, py-r*.65),
            size=(r*1.30, r*1.30)
        )

        Color(1, 1, 1, .98)
        Ellipse(
            pos=(px-r*.30, py-r*.30),
            size=(r*.60, r*.60)
        )

        # Rotating beam
        ang = g.pulsar_beam_angle()
        beam_len = max(330, r*7.5)
        dx = math.cos(ang)
        dy = math.sin(ang)

        # Opposite beam pair
        for sign in (-1, 1):
            ex = px + dx * beam_len * sign
            ey = py + dy * beam_len * sign

            Color(.18, .72, 1.0, .09)
            Line(
                points=[px, py, ex, ey],
                width=max(8, r*.14)
            )

            Color(.55, .92, 1.0, .32)
            Line(
                points=[px, py, ex, ey],
                width=max(3.5, r*.055)
            )

            Color(.95, 1.0, 1.0, .82)
            Line(
                points=[px, py, ex, ey],
                width=max(1.2, r*.018)
            )

        # Firing hit flash
        if g.last_hit_flash > 0:
            Color(1, .25, .05, min(.45, g.last_hit_flash))
            Ellipse(
                pos=(px-r*1.15, py-r*1.15),
                size=(r*2.30, r*2.30)
            )

        # Target reticle
        Color(.25, 1.0, .75, .75)
        Line(circle=(px, py, r*1.32), width=max(1.2, r*.012))
        Line(points=[px-r*1.55,py,px-r*1.20,py], width=1.3)
        Line(points=[px+r*1.20,py,px+r*1.55,py], width=1.3)

    def redraw(self):
        g = self.game
        self.canvas.clear()
        now = time.time()

        with self.canvas:
            # ==================================================
            # UZAY
            # ==================================================
            Color(0.002, 0.004, 0.012, 1)
            Rectangle(pos=(0, 0), size=(1100, 700))

            Color(0.07, 0.02, 0.10, 0.12)
            Ellipse(pos=(650, 390), size=(430, 260))

            Color(0.02, 0.08, 0.15, 0.10)
            Ellipse(pos=(760, 470), size=(280, 170))

            # ==================================================
            # YILDIZLAR / PARALLAX
            # ==================================================
            for s in self.stars:
                p = self.project(s["x"], s["z"], s["y"])
                if not p:
                    continue

                sx, sy, depth = p

                if -40 < sx < 1140 and -40 < sy < 740:
                    size = max(0.8, min(5.0, s["size"] * 1500 / depth))
                    alpha = min(1.0, 0.35 + 1200 / depth)

                    Color(0.78, 0.89, 1, alpha)
                    Ellipse(
                        pos=(sx-size/2, sy-size/2),
                        size=(size, size)
                    )

                    if g.nitro and g.forward:
                        Color(0.25, 0.65, 1, 0.12)
                        Line(
                            points=[550, 375, sx, sy],
                            width=1
                        )

            # ==================================================
            # OYUN BAŞLANGICI: BAZ İSTASYONU + METEOR YAĞMURU
            # ==================================================
            self.draw_station()
            self.draw_meteors()
            self.draw_pickups()
            self.draw_wormhole()

            # Yeni seviyeler
            self.draw_supernova_level()
            self.draw_lost_station()
            self.draw_enemy_fleet()
            self.draw_crystal_level()
            self.draw_omega()
            self.draw_player_weapon_laser()

            # ==================================================
            # SEVİYEDEKİ KARA DELİKLER
            # ==================================================
            for bh in g.blackholes:
                self.draw_gargantua(bh)

            # Level 2 son boss
            self.draw_void_master()

            # Level 3 boss
            self.draw_pulsar()

            # ==================================================
            # NITRO RENK EFEKTİ
            # ==================================================
            if g.nitro and g.forward and g.fuel > 0:
                nr, ng, nb, _ = g.get_nitro_rgba()
                now_nitro = time.time()

                # Camın tamamında hafif seçili Nitro rengi.
                Color(nr, ng, nb, .075)
                Rectangle(pos=(145,180), size=(810,475))

                # Hız çizgileri: ilk şahıs hız hissi.
                for i in range(14):
                    phase = (
                        (i * 71 + now_nitro * 310)
                        % 690
                    )

                    x = 205 + phase
                    side = -1 if x < 550 else 1

                    y1 = 220 + ((i * 43) % 360)
                    y2 = y1 + 58 + (i % 4) * 16

                    drift = side * (18 + (i % 3) * 7)

                    Color(nr, ng, nb, .28 + (i % 3)*.08)
                    Line(
                        points=[
                            x, y1,
                            x + drift, min(635,y2)
                        ],
                        width=1.4 + (i % 2)
                    )

                # Kokpit kenarlarında enerji parlaması.
                Color(nr, ng, nb, .42)
                Line(points=[190,615,292,192], width=3)
                Line(points=[910,615,808,192], width=3)

            # ==================================================
            # GERCEK KOKPIT ICI GORUNUM
            # ==================================================
            # On camda cok hafif mavi cam tonu
            Color(.03, .10, .16, .055)
            Rectangle(pos=(145, 180), size=(810, 475))

            # --------------------------------------------------
            # UST KANOPI / TAVAN
            # --------------------------------------------------
            Color(.018, .028, .042, 1)
            Triangle(points=[0,700, 225,700, 175,625])
            Triangle(points=[1100,700, 875,700, 925,625])
