    # ======================================================
    # KAYIT / CHECKPOINT / GELİŞTİRME
    # ======================================================

    def load_progress(self):
        try:
            if os.path.exists(self.save_file):
                with open(self.save_file, "r", encoding="utf-8") as f:
                    data = json.load(f)

                self.unlocked_level = int(data.get("unlocked_level", 1))
                self.credits = int(data.get("credits", 0))

                saved_upgrades = data.get("upgrades", {})
                for key in self.upgrades:
                    self.upgrades[key] = max(
                        0,
                        min(3, int(saved_upgrades.get(key, 0)))
                    )

                saved_stars = data.get("best_stars", {})
                for key in self.best_stars:
                    self.best_stars[key] = max(
                        0,
                        min(3, int(saved_stars.get(key, 0)))
                    )

                # Mağaza kayıtları
                self.shop_shield_level = max(
                    0,
                    min(3, int(data.get("shop_shield_level", 0)))
                )

                saved_colors = data.get(
                    "unlocked_nitro_colors",
                    ["cyan"]
                )

                valid_colors = [
                    c for c in saved_colors
                    if c in self.nitro_colors
                ]

                if "cyan" not in valid_colors:
                    valid_colors.insert(0, "cyan")

                self.unlocked_nitro_colors = valid_colors

                selected = data.get(
                    "selected_nitro_color",
                    "cyan"
                )

                if selected not in self.unlocked_nitro_colors:
                    selected = "cyan"

                self.selected_nitro_color = selected

                # 100 günlük seri kayıtları
                self.daily_streak_day = max(
                    0,
                    min(100, int(data.get("daily_streak_day", 0)))
                )
                self.daily_last_claim = str(
                    data.get("daily_last_claim", "")
                )
                self.daily_total_claims = max(
                    0,
                    int(data.get("daily_total_claims", 0))
                )
                self.daily_cycle_complete = bool(
                    data.get("daily_cycle_complete", False)
                )
        except Exception:
            # Save bozulursa oyun yine açılır.
            self.unlocked_level = 1
            self.credits = 0

    def save_progress(self):
        data = {
            "unlocked_level": self.unlocked_level,
            "credits": self.credits,
            "upgrades": self.upgrades,
            "best_stars": self.best_stars,

            # Mağaza
            "shop_shield_level": self.shop_shield_level,
            "unlocked_nitro_colors": self.unlocked_nitro_colors,
            "selected_nitro_color": self.selected_nitro_color,

            # 100 günlük seri
            "daily_streak_day": self.daily_streak_day,
            "daily_last_claim": self.daily_last_claim,
            "daily_total_claims": self.daily_total_claims,
            "daily_cycle_complete": self.daily_cycle_complete
        }

        try:
            with open(self.save_file, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    # ======================================================
    # 100 GÜNLÜK SERİ
    # ======================================================

    def daily_reward_for_day(self, day):
        """
        Normal günler yükselen kredi verir.
        Her 10. gün büyük ödül.
        100. gün 5000 kredi.
        """
        day = max(1, min(100, int(day)))

        milestones = {
            10: 500,
            20: 750,
            30: 1000,
            40: 1250,
            50: 1500,
            60: 1800,
            70: 2200,
            80: 2600,
            90: 3200,
            100: 5000,
        }

        if day in milestones:
            return milestones[day]

        # 1. gün 60 kredi, sonra kademeli artar.
        return 50 + day * 10

    def daily_today(self):
        return date.today()

    def daily_claim_status(self):
        """
        Dönüş:
        can_claim, next_day, reset_happened
        """
        today = self.daily_today()

        if not self.daily_last_claim:
            return True, 1, False

        try:
            last = date.fromisoformat(self.daily_last_claim)
        except Exception:
            return True, 1, True

        diff = (today - last).days

        # Aynı gün ikinci kez ödül yok.
        if diff == 0:
            return False, self.daily_streak_day, False

        # Saat/tarih geri alınmışsa güvenli davran.
        if diff < 0:
            return False, self.daily_streak_day, False

        # Dün aldıysa seri devam eder.
        if diff == 1:
            if self.daily_streak_day >= 100:
                return True, 1, False
            return True, self.daily_streak_day + 1, False

        # Bir veya daha fazla gün kaçırılmış.
        return True, 1, True

    def claim_daily_reward(self):
        can_claim, next_day, reset = self.daily_claim_status()

        if not can_claim:
            self.show_daily_streak(
                "BUGÜNKÜ ÖDÜL ZATEN ALINDI"
            )
            return

        reward = self.daily_reward_for_day(next_day)

        self.daily_streak_day = next_day
        self.daily_last_claim = self.daily_today().isoformat()
        self.daily_total_claims += 1
        self.credits += reward

        if next_day == 100:
            self.daily_cycle_complete = True
            msg = f"100. GÜN! +{reward} KREDİ • SERİ TAMAMLANDI!"
        elif reset:
            self.daily_cycle_complete = False
            msg = f"SERİ YENİDEN BAŞLADI • +{reward} KREDİ"
        else:
            msg = f"{next_day}. GÜN ÖDÜLÜ • +{reward} KREDİ"

        self.save_progress()
        self.show_daily_streak(msg)

    def show_daily_streak(self, message=""):
        self.state = "menu"

        self.game_ui.opacity = 0
        self.game_ui.disabled = True

        self.menu_ui.clear_widgets()
        self.menu_ui.opacity = 1
        self.menu_ui.disabled = False

        shade = Widget()
        with shade.canvas:
            Color(0, .004, .018, .97)
            Rectangle(pos=(0,0), size=(1100,700))

            Color(.012,.032,.052,.98)
            Rectangle(pos=(55,55), size=(990,590))

            Color(.10,.65,1,.72)
            Line(rectangle=(55,55,990,590), width=2)

        self.menu_ui.add_widget(shade)

        self.menu_ui.add_widget(Label(
            text=f"{self.tr('daily')}   •   {self.tr('credits')}: {self.credits}",
            font_size=30,
            bold=True,
            color=(.42,.90,1,1),
            size_hint=(None,None),
            size=(760,48),
            pos=(170,590)
        ))

        can_claim, next_day, reset = self.daily_claim_status()

        current_display = self.daily_streak_day
        if can_claim:
            target_display = next_day
        else:
            target_display = current_display

        # Üst bilgi
        if self.daily_streak_day == 0:
            status_text = "SERİ HENÜZ BAŞLAMADI"
        elif can_claim and reset:
            status_text = (
                f"ÖNCEKİ SERİ: {self.daily_streak_day} GÜN • "
                f"BUGÜN 1. GÜNDEN BAŞLAR"
            )
        elif can_claim:
            status_text = (
                f"MEVCUT SERİ: {self.daily_streak_day} GÜN • "
                f"SIRADAKİ: {next_day}. GÜN"
            )
        else:
            status_text = (
                f"MEVCUT SERİ: {self.daily_streak_day} / 100 GÜN • "
                f"BUGÜNKÜ ÖDÜL ALINDI"
            )

        self.menu_ui.add_widget(Label(
            text=status_text,
            font_size=16,
            bold=True,
            color=(1,.72,.25,1),
            size_hint=(None,None),
            size=(850,30),
            pos=(125,552)
        ))

        # --------------------------------------------------
        # 10 x 10 = 100 günlük takvim
        # --------------------------------------------------
        grid_x = 105
        grid_y = 205
        cell_w = 82
        cell_h = 31
        gap_x = 9
        gap_y = 5

        for day_num in range(1,101):
            row = (day_num-1)//10
            col = (day_num-1)%10

            x = grid_x + col*(cell_w+gap_x)
            y = grid_y + (9-row)*(cell_h+gap_y)

            milestone = day_num % 10 == 0
            claimed = (
                self.daily_streak_day > 0
                and day_num <= self.daily_streak_day
                and not reset
            )
            current = (
                can_claim and day_num == next_day
            ) or (
                not can_claim and day_num == self.daily_streak_day
            )

            # Kutunun rengi
            if current:
                bg = (.08,.52,.72,.98)
            elif claimed:
                bg = (.05,.38,.20,.94)
            elif milestone:
                bg = (.33,.13,.45,.94)
            else:
                bg = (.055,.09,.14,.94)

            day_btn = Button(
                text=str(day_num),
                font_size=12,
                bold=milestone or current,
                size_hint=(None,None),
                size=(cell_w,cell_h),
                pos=(x,y),
                background_normal="",
                background_color=bg,
                color=(1,1,1,1)
            )
            day_btn.disabled = True
            self.menu_ui.add_widget(day_btn)

        # --------------------------------------------------
        # Alt ödül bilgisi
        # --------------------------------------------------
        reward_day = next_day if can_claim else max(1,self.daily_streak_day)
        reward = self.daily_reward_for_day(reward_day)

        if can_claim:
            reward_text = (
                f"BUGÜN: {reward_day}. GÜN   •   "
                f"ÖDÜL: {reward} KREDİ"
            )
        else:
            reward_text = (
                f"{self.daily_streak_day}. GÜN TAMAMLANDI   •   "
                f"YARIN DEVAM ET"
            )

        self.menu_ui.add_widget(Label(
            text=reward_text,
            font_size=18,
            bold=True,
            color=(.35,1,.62,1),
            size_hint=(None,None),
            size=(650,36),
            pos=(225,152)
        ))

        if message:
            self.menu_ui.add_widget(Label(
                text=message,
                font_size=15,
                bold=True,
                color=(1,.62,.16,1),
                size_hint=(None,None),
                size=(760,30),
                pos=(170,120)
            ))

        claim_btn = Button(
            text=(
                self.tr("claim")
                if can_claim
                else "BUGÜN ALINDI"
            ),
            font_size=17,
            bold=True,
            size_hint=(None,None),
            size=(250,48),
            pos=(285,66),
            background_normal="",
            background_color=(
                (.04,.48,.28,.98)
                if can_claim
                else (.10,.14,.18,.88)
            )
        )
        claim_btn.disabled = not can_claim
        claim_btn.bind(
            on_release=lambda *_:self.claim_daily_reward()
        )
        self.menu_ui.add_widget(claim_btn)

        back_btn = Button(
            text="← ANA MENÜ",
            font_size=17,
            bold=True,
            size_hint=(None,None),
            size=(250,48),
            pos=(565,66),
            background_normal="",
            background_color=(.12,.16,.24,.96)
        )
        back_btn.bind(on_release=lambda *_:self.show_menu())
        self.menu_ui.add_widget(back_btn)

    # ======================================================
    # MAĞAZA
    # ======================================================

    def get_nitro_rgba(self):
        return self.nitro_colors.get(
            self.selected_nitro_color,
            self.nitro_colors["cyan"]
        )

    def refresh_nitro_button_color(self):
        if hasattr(self, "nitro_button"):
            self.nitro_button.background_color = self.get_nitro_rgba()

    def shop_shield_cost(self):
        costs = [500, 900, 1500]
        if self.shop_shield_level >= 3:
            return None
        return costs[self.shop_shield_level]

    def buy_shop_shield(self):
        if self.shop_shield_level >= 3:
            return

        cost = self.shop_shield_cost()
        if cost is None or self.credits < cost:
            self.show_shop_menu("YETERSİZ KREDİ")
            return

        self.credits -= cost
        self.shop_shield_level += 1

        # Menüdeyken satın alındı; bir sonraki görevde tam kapasite kullanılır.
        self.save_progress()
        self.show_shop_menu("KALKAN KORUMASI SATIN ALINDI")

    def buy_or_select_nitro_color(self, color_key):
        if color_key not in self.nitro_colors:
            return

        if color_key in self.unlocked_nitro_colors:
            self.selected_nitro_color = color_key
            self.refresh_nitro_button_color()
            self.save_progress()
            self.show_shop_menu("NITRO RENGİ SEÇİLDİ")
            return

        cost = self.nitro_color_costs[color_key]

        if self.credits < cost:
            self.show_shop_menu("YETERSİZ KREDİ")
            return

        self.credits -= cost
        self.unlocked_nitro_colors.append(color_key)
        self.selected_nitro_color = color_key

        self.refresh_nitro_button_color()
        self.save_progress()
        self.show_shop_menu("NITRO RENGİ AÇILDI")

