    def upgrade_cost(self, key):
        return 100 + self.upgrades[key] * 125

    def buy_upgrade(self, key):
        if self.upgrades[key] >= 3:
            return

        cost = self.upgrade_cost(key)
        if self.credits < cost:
            return

        self.credits -= cost
        self.upgrades[key] += 1
        self.save_progress()
        self.show_upgrade_menu()

