    # ======================================================
    # HASAR / KAPSÜLLER
    # ======================================================

    def max_shield(self):
        return (
            100.0
            + self.upgrades["shield"] * 20.0
            + self.shop_shield_level * 25.0
        )

    def apply_damage(self, amount):
        if self.dead:
            return

        # Mağazadan alınan Kalkan Koruması gelen hasarı azaltır.
        protection = min(.15, self.shop_shield_level * .05)
        amount = max(0.0, amount * (1.0 - protection))

        self.level_damage_taken += amount
        self.damage_flash = 1.0

        absorbed = min(self.shield, amount)
        self.shield -= absorbed
        remaining = amount - absorbed

        if remaining > 0:
            self.hull = max(0.0, self.hull - remaining)

        if self.hull <= 0:
            self.dead = True
            self.forward_velocity = 0
            self.lateral_velocity = 0
            self.warning_label.text = "GEMİ GÖVDESİ KRİTİK • GÖREV BAŞARISIZ"
            self.warning_label.color = (1,.05,.02,1)
            Clock.schedule_once(lambda _dt:self.show_menu(), 2.2)

    def spawn_pickups_for_level(self):
        self.pickups = []

        if self.level == 1:
            items = [
                ("shield", -520, -1900),
                ("repair", 480, -650),
            ]
        elif self.level == 2:
            items = [
                ("repair", -420, -2450),
                ("shield", 390, -1250),
                ("shield", 0, 540),
            ]
        elif self.level == 3:
            items = [
                ("shield", -520, -1200),
                ("repair", 530, -550),
            ]
        elif self.level == 4:
            items = [
                ("shield", -420, -2350),
                ("repair", 440, -1550),
                ("shield", -250, -650),
            ]
        elif self.level == 5:
            items = [
                ("shield", -420, -1500),
                ("repair", 480, 300),
            ]
        elif self.level == 6:
            items = [
                ("shield", 520, -500),
                ("repair", -460, 1550),
            ]
        elif self.level == 7:
            items = [
                ("repair", 520, -1000),
                ("shield", -500, -200),
            ]
        elif self.level == 8:
            items = [
                ("shield", -500, -1500),
                ("repair", 520, -500),
            ]
        elif self.level == 9:
            items = [
                ("shield", 520, -1900),
                ("repair", -520, -400),
            ]
        elif self.level == 20:
            items = [
                ("shield", -600, -1500),
                ("repair", 600, -900),
            ]
        else:
            items = []

        for typ,x,z in items:
            self.pickups.append({
                "type": typ,
                "x": x,
                "z": z,
                "y": random.uniform(-80, 90),
                "collected": False
            })

    def update_pickups(self):
        for item in self.pickups:
            if item["collected"]:
                continue

            dx = item["x"] - self.ship_x
            dz = item["z"] - self.ship_z

            if abs(dx) < 125 and abs(dz) < 150:
                item["collected"] = True
                self.level_pickups_collected += 1
                self.pickup_message_time = 2.0

                if item["type"] == "repair":
                    self.hull = min(100.0, self.hull + 35.0)
                    self.warning_label.text = "🟢 TAMİR KAPSÜLÜ • GÖVDE ONARILDI"
                    self.warning_label.color = (.25,1,.52,1)
                else:
                    self.shield = min(self.max_shield(), self.shield + 45.0)
                    self.warning_label.text = "🔵 KALKAN KAPSÜLÜ • KALKAN YÜKLENDİ"
                    self.warning_label.color = (.25,.78,1,1)

    # ======================================================
    # BOSS GİRİŞ SİNEMATİĞİ
    # ======================================================

    def start_cinematic(self, name, callback, duration=2.8):
        self.cinematic_active = True
        self.cinematic_name = name
        self.cinematic_callback = callback

        self.forward = self.backward = False
        self.left = self.right = False
        self.nitro = False
        self.fire_pressed = False

        if name == "VOID MASTER":
            self.cinematic_label.text = (
                "UNKNOWN GRAVITATIONAL SIGNAL DETECTED...\n"
                "VOID MASTER"
            )
            self.cinematic_label.color = (.82,.42,1,1)

        elif name == "PULSAR":
            self.cinematic_label.text = (
                "NEUTRON STAR WEAPON SIGNATURE...\n"
                "PULSAR"
            )
            self.cinematic_label.color = (.42,.86,1,1)

        elif name == "OMEGA":
            self.cinematic_label.text = (
                "FINAL GRAVITATIONAL ENTITY DETECTED...\n"
                "VOID MASTER OMEGA"
            )
            self.cinematic_label.color = (1,.18,.38,1)

        else:
            self.cinematic_label.text = (
                "SPACE-TIME COLLAPSE DETECTED...\n"
                "WORMHOLE ESCAPE"
            )
            self.cinematic_label.color = (.42,.86,1,1)

        self.cinematic_label.opacity = 1
        Clock.schedule_once(self.finish_cinematic, duration)

    def finish_cinematic(self, _dt):
        self.cinematic_active = False
        self.cinematic_label.opacity = 0

        cb = self.cinematic_callback
        self.cinematic_callback = None

        if cb:
            cb()

    # ======================================================
    # LEVEL 4 - SOLUCAN DELİĞİ KAÇIŞI
    # ======================================================

    def wormhole_update(self, dt):
        if self.level != 4 or not self.wormhole:
            return

        if self.wormhole_tunnel_active:
            self.wormhole_tunnel_time += dt

            # tunnel speed
            self.forward_velocity = 900
            self.camera_shake_x = math.sin(time.time()*40)*4
            self.camera_shake_y = math.cos(time.time()*44)*3

            if self.wormhole_tunnel_time >= 3.2:
                self.wormhole_tunnel_active = False
                self.complete_level()
            return

        self.wormhole_timer += dt

        dx = self.wormhole["x"] - self.ship_x
        dz = self.wormhole["z"] - self.ship_z
        distance = max(1.0, math.hypot(dx,dz))

        # Space collapse pulls the ship toward the portal.
        if distance < 1900:
            pull = 45 + ((1900-distance)/1900)**2 * 260
            self.lateral_velocity += (dx/distance) * pull * dt
            self.forward_velocity += (dz/distance) * pull * dt

        # Increasing instability.
        urgency = min(1.0, self.wormhole_timer / self.wormhole_limit)
        self.danger_intensity = max(self.danger_intensity, urgency*.72)

        if self.wormhole_timer > self.wormhole_limit:
            self.apply_damage(150)
            if not self.dead:
                self.dead = True
                Clock.schedule_once(lambda _dt:self.show_menu(), 2.0)
            return

        if distance < 230:
            self.wormhole_tunnel_active = True
            self.wormhole_tunnel_time = 0
            self.forward = self.backward = False
            self.left = self.right = False
            self.warning_label.text = "SOLUCAN DELİĞİNE GİRİLDİ • TÜNEL ATLAMASI"
            self.warning_label.color = (.35,.90,1,1)

    # ======================================================
    # LEVEL 5 - SUPERNOVA ESCAPE
    # ======================================================

    def supernova_update(self, dt):
        if self.level != 5 or not self.supernova_active:
            return

        self.supernova_damage_cooldown = max(
            0.0,self.supernova_damage_cooldown-dt
        )

        # Şok dalgası sürekli gemiye yaklaşır.
        self.supernova_wave_z += 310.0 * dt
        gap = self.ship_z - self.supernova_wave_z

        self.danger_intensity = max(
            self.danger_intensity,
            max(0.0,min(1.0,(1550-gap)/1550))
        )

        if gap < 180 and self.supernova_damage_cooldown <= 0:
            self.apply_damage(24.0)
            self.supernova_damage_cooldown = .55
            self.warning_label.text = "☀ SÜPERNOVA DALGASI GEMİYE ULAŞTI!"
            self.warning_label.color = (1,.18,.02,1)

        if self.ship_z >= self.supernova_goal_z:
            self.supernova_active = False
            self.complete_level()

    # ======================================================
    # LEVEL 7 - LOST SPACE STATION
    # ======================================================

    def lost_station_update(self, dt):
        if self.level != 7 or not self.lost_station:
            return

        self.station_pulse_timer += dt
        self.station_pulse_flash = max(0.0,self.station_pulse_flash-dt*.8)

        dx = self.lost_station["x"]-self.ship_x
        dz = self.lost_station["z"]-self.ship_z
        distance = max(1.0,math.hypot(dx,dz))

        # Oyuncu istasyonun yakınında ama çok dibinde değilse tarama ilerler.
        if 280 < distance < 680:
            self.station_scan_progress += dt
            self.forward_velocity *= .92

            self.warning_label.text = (
                f"İSTASYON TARANIYOR  "
                f"{int(100*self.station_scan_progress/self.station_scan_required)}%"
            )
            self.warning_label.color = (.30,1,.66,1)

        elif distance <= 280:
            self.warning_label.text = "⚠ İSTASYONA FAZLA YAKINSIN • EMP RİSKİ"
            self.warning_label.color = (1,.38,.05,1)
        else:
            self.warning_label.text = "KAYIP İSTASYONA YAKLAŞ • TARAMA MENZİLİ 680"
            self.warning_label.color = (.42,.88,1,1)

        # EMP pulse every 3.8 seconds
        if self.station_pulse_timer >= 3.8:
            self.station_pulse_timer = 0.0
            self.station_pulse_flash = 1.0

            if distance < 360:
                self.apply_damage(18.0)
                self.warning_label.text = "⚡ EMP DARBESİ! KALKAN HASAR ALDI"
                self.warning_label.color = (1,.25,.06,1)

        if self.station_scan_progress >= self.station_scan_required:
            self.complete_level()

    # ======================================================
    # LEVEL 8 - DARK FLEET
    # ======================================================

    def dark_fleet_update(self, dt):
        if self.level != 8:
            return

        self.fire_cooldown = max(0.0,self.fire_cooldown-dt)
        self.enemy_fire_timer += dt
        self.enemy_laser_flash = max(0.0,self.enemy_laser_flash-dt*2.5)
        self.player_laser_flash = max(0.0,self.player_laser_flash-dt*3.2)

        now = time.time()

        # Hafif savaş manevrası.
        for i,e in enumerate(self.enemy_fleet):
            if e["hp"] <= 0:
                continue
            e["x"] = e["base_x"] + math.sin(now*.8+i*1.7)*110

        # Ateş: nişangaha en yakın düşmana vur.
        if self.fire_pressed and self.fire_cooldown <= 0:
            self.fire_cooldown = .17

            candidates = []
            for e in self.enemy_fleet:
                if e["hp"] <= 0:
                    continue
                rel_z = e["z"]-self.ship_z
                if rel_z <= 0:
                    continue
                aim = abs((e["x"]-self.ship_x)/max(1,rel_z))
                if aim < .17 and rel_z < 2500:
                    candidates.append((aim,rel_z,e))

            if candidates:
                candidates.sort(key=lambda x:(x[0],x[1]))
                e = candidates[0][2]
                damage = 5.0 + self.upgrades["weapon"]*2.0
                e["hp"] = max(0,e["hp"]-damage)

                self.player_laser_target = (e["x"],e["z"],e.get("y",0))
                self.player_laser_flash = .40

        # Enemy fire.
        alive = [e for e in self.enemy_fleet if e["hp"] > 0]
        if alive and self.enemy_fire_timer >= 2.3:
            self.enemy_fire_timer = 0.0
            shooter = random.choice(alive)
            self.enemy_laser_origin = (
                shooter["x"],shooter["z"],shooter.get("y",0)
            )
            self.enemy_laser_flash = .45

            rel_z = shooter["z"]-self.ship_z
            aim_error = abs(shooter["x"]-self.ship_x)

            if rel_z > 0 and rel_z < 2300 and aim_error < 650:
                chance = .60 if not (self.left or self.right) else .28
                if random.random() < chance:
                    self.apply_damage(12.0)

        # Filonun çok ötesine geçip savaştan kaçmayı önle.
        if alive and self.ship_z > -600:
            self.forward_velocity *= .92

        if not alive:
            self.complete_level()

    # ======================================================
    # LEVEL 9 - CRYSTAL GALAXY
    # ======================================================

    def crystal_level_update(self, dt):
        if self.level != 9:
            return

        self.crystal_hit_cooldown = max(
            0.0,self.crystal_hit_cooldown-dt
        )
        self.fire_cooldown = max(0.0,self.fire_cooldown-dt)

        # Crystal collisions
        for c in self.crystals:
            if c.get("broken"):
                continue

            dx = c["x"]-self.ship_x
            dz = c["z"]-self.ship_z

            if (
                abs(dx) < 105
                and abs(dz) < 130
                and self.crystal_hit_cooldown <= 0
            ):
                c["broken"] = True
                self.apply_damage(15.0)
                self.crystal_hit_cooldown = .35
                self.warning_label.text = "◆ KRİSTAL ÇARPMASI!"
                self.warning_label.color = (.80,.28,1,1)

        # Boss combat
        if self.crystal_boss:
            rel_z = self.crystal_boss["z"]-self.ship_z
            dx = self.crystal_boss["x"]-self.ship_x

            if rel_z < 1550 and rel_z > 0:
                self.warning_label.text = (
                    f"CRYSTAL LEVIATHAN  {int(self.crystal_boss_health)}%"
                )
                self.warning_label.color = (.70,.32,1,1)

                # Keep combat area from being passed too quickly
                if self.ship_z > 1200:
                    self.forward_velocity *= .92

                if self.fire_pressed and self.fire_cooldown <= 0:
                    self.fire_cooldown = .16
                    aim = abs(dx/max(1,rel_z))

                    if aim < .17:
                        damage = 4.5 + self.upgrades["weapon"]*1.7
                        self.crystal_boss_health = max(
                            0.0,self.crystal_boss_health-damage
                        )
                        self.player_laser_target = (
                            self.crystal_boss["x"],
                            self.crystal_boss["z"],
                            0
                        )
                        self.player_laser_flash = .35

            if self.crystal_boss_health <= 0:
                self.complete_level()

        self.player_laser_flash = max(
            0.0,self.player_laser_flash-dt*3.0
        )

    # ======================================================
    # LEVEL 20 - VOID MASTER OMEGA
    # ======================================================

    def omega_update(self, dt):
        if self.level != 20 or not self.omega:
            return

        if self.omega_exploding:
            self.omega_explosion_time += dt
            self.camera_shake_x = math.sin(time.time()*45)*18*(1-min(1,self.omega_explosion_time/3))
            self.camera_shake_y = math.cos(time.time()*51)*12*(1-min(1,self.omega_explosion_time/3))

            if self.omega_explosion_time >= 3.0:
                self.complete_level()
            return

        self.fire_cooldown = max(0.0,self.fire_cooldown-dt)
        self.omega_attack_timer += dt

        ox = self.omega["x"]
        oz = self.omega["z"]
        dx = ox-self.ship_x
        dz = oz-self.ship_z
        distance = max(1.0,math.hypot(dx,dz))
        rel_z = oz-self.ship_z

        hp_ratio = max(0,self.omega_health)/300.0
        phase = 1 if hp_ratio > .66 else (2 if hp_ratio > .33 else 3)

        # Final boss gravity.
        if distance < 1800:
            pull = 45 + (1-distance/1800)**2 * (280+phase*100)
            self.lateral_velocity += (dx/distance)*pull*dt
            self.forward_velocity += (dz/distance)*pull*dt

        # Fire at Omega
        if (
            self.fire_pressed
            and self.fire_cooldown <= 0
            and rel_z > 0
            and rel_z < 2500
        ):
            self.fire_cooldown = .14
            aim = abs(dx/max(1,rel_z))

            if aim < .16:
                damage = 3.8 + self.upgrades["weapon"]*1.8
                self.omega_health = max(0,self.omega_health-damage)
                self.player_laser_target = (ox,oz,0)
                self.player_laser_flash = .32

        self.player_laser_flash = max(
            0.0,self.player_laser_flash-dt*3.2
        )

        # Gamma attack
        if not self.omega_gamma_active:
            attack_interval = 4.8 if phase == 1 else (3.8 if phase == 2 else 2.9)

            if self.omega_attack_timer >= attack_interval:
                self.omega_attack_timer = 0.0
                self.omega_gamma_active = True
                self.omega_gamma_started = time.time()
                self.omega_gamma_target_x = self.ship_x
                self.omega_gamma_damage_done = False
                self.warning_label.text = "☢ OMEGA GAMA KİLİDİ • YANA KAÇ!"
                self.warning_label.color = (1,.10,.22,1)

        else:
            elapsed = time.time()-self.omega_gamma_started

            if 1.0 <= elapsed < 1.7 and not self.omega_gamma_damage_done:
                self.omega_gamma_damage_done = True

                if abs(self.ship_x-self.omega_gamma_target_x) < 250:
                    self.apply_damage(26 + phase*4)
                    self.warning_label.text = "☢ OMEGA GAMA İSABETİ!"
                    self.warning_label.color = (1,.05,.15,1)

            if elapsed >= 1.7:
                self.omega_gamma_active = False

        # Phase 2/3 energy orbs.
        if phase >= 2:
            wanted = 2 if phase == 2 else 4

            while len([o for o in self.omega_orbs if o.get("active",True)]) < wanted:
                side = random.choice((-1,1))
                self.omega_orbs.append({
                    "x": ox + side*random.uniform(350,800),
                    "z": oz-random.uniform(100,500),
                    "y": random.uniform(-150,150),
                    "speed": random.uniform(180,260) + phase*25,
                    "active": True
                })

            for orb in self.omega_orbs:
                if not orb.get("active",True):
                    continue

                ddx = self.ship_x-orb["x"]
                ddz = self.ship_z-orb["z"]
                dist = max(1,math.hypot(ddx,ddz))

                orb["x"] += (ddx/dist)*orb["speed"]*dt
                orb["z"] += (ddz/dist)*orb["speed"]*dt

                if dist < 125:
                    orb["active"] = False
                    self.apply_damage(14 + phase*3)

                if orb["z"] < self.ship_z-250:
                    orb["active"] = False

        self.warning_label.text = (
            f"VOID MASTER OMEGA  {int(self.omega_health)}/300"
            f"   •   FAZ {phase}"
        )
        self.warning_label.color = (
            (0.75,.35,1,1)
            if phase < 3
            else (1,.12,.15,1)
        )

        self.danger_intensity = max(
            self.danger_intensity,
            .32 + phase*.18
        )

        if self.omega_health <= 0 and not self.omega_exploding:
            self.omega_exploding = True
            self.omega_explosion_time = 0.0
            self.fire_pressed = False
            self.warning_label.text = "OMEGA ÇEKİRDEĞİ ÇÖKÜYOR!"
            self.warning_label.color = (1,.70,.20,1)

